#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end;
    long n = strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long k = strtol(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 1 || k < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (k > 1000000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long survivor = 0; // 0‑based index
    for (long i = 2; i <= n; ++i) {
        survivor = (survivor + k) % i;
    }
    printf("%ld\n", survivor + 1);
    return 0;
}
